def dist(src):
 d={src:0}; q=deque([src])
 while q:
  r,c=q.popleft()
  for p in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if p in walk and p not in d:d[p]=d[(r,c)]+1;q.append(p)
 return d
